INSERT INTO public.contents (type, title, subtitle, description, author, tags, category, slug, cover, rating, rating_count, formats, language, year, views, read_time, episode_count, price_cents, currency, published, featured, collection) VALUES ('manga', 'Kaze no Kokoro', 'O vento lembra de tudo', E'Sano é um aprendiz de samurai com um dom que ninguém entende: o vento sussurra os movimentos antes que aconteçam. Sob a tutela do severo mestre Goro, ele descobre que o verdadeiro golpe não é o mais rápido — é o mais sincero.\n\nUma saga de ação e formação sobre honra, perda e o primeiro corte que nunca se esquece.', 'Haruto Sano', ARRAY['Ação','Aventura','Artes marciais'], 'Shonen', 'kaze-no-kokoro', '/covers/manga-kaze.jpg', 4.80, 1240, ARRAY['digital'], 'pt', 2024, 48200, 24, 3, 1290, 'BRL', true, true, 'Em andamento'), ('manga', 'Ramen da Meia-Noite', 'Uma tigela, mil histórias', E'Entre a última e a primeira hora do dia, a barraca do tio Genshin abre para quem não consegue dormir: estudantes exaustos, motoristas de táxi, corações partidos. Cada cliente traz uma história — e o ramen sempre sai do ponto.\n\nComédia calorosa sobre os sabores que consolam de madrugada.', 'Yuki Tanabe', ARRAY['Comédia','Culinária','Vida diária'], 'Slice of Life', 'ramen-da-meia-noite', '/covers/manga-ramen.jpg', 4.60, 860, ARRAY['digital'], 'pt', 2023, 22150, 18, 2, 790, 'BRL', true, false, 'Em andamento'), ('manga', 'Sigilo', 'A cidade não conta segredos', E'O detetive Aizawa só aceita casos que a chuva encobre. Quando uma testemunha desaparece antes do depoimento, ele percebe que o crime não é isolado — é um sistema. Cada resposta compra silêncio; cada silêncio tem preço.\n\nNoir psicológico de ritmos curtos e sombras longas.', 'Ren Kobayashi', ARRAY['Mistério','Psicológico','Noir'], 'Seinen', 'sigilo', '/covers/manga-sigilo.jpg', 4.90, 2100, ARRAY['digital'], 'pt', 2022, 67300, 32, 2, 1490, 'BRL', true, false, 'Completo'), ('manga', 'Estrela Cadente', 'Um verão para não esquecer', E'No festival de fim de verão, Chihiro vê uma estrela cadente ao mesmo tempo que Kai — e os dois pedem o mesmo desejo. Só que desejos divididos cobram juros.\n\nRomance shoujo sobre coragem de dizer, calar e recomeçar.', 'Mika Aizawa', ARRAY['Romance','Festival','Drama'], 'Shoujo', 'estrela-cadente', '/covers/manga-estrela.jpg', 4.70, 980, ARRAY['digital'], 'pt', 2024, 31400, 21, 2, 990, 'BRL', true, false, 'Em andamento') ON CONFLICT (slug) DO NOTHING; INSERT INTO public.content_episodes (content_id, number, title, body, images, is_free, published_at) SELECT c.id, e.number, e.title, e.body, e.images, e.is_free, now() - (e.number * interval '7 days') FROM public.contents c JOIN (VALUES ('kaze-no-kokoro', 1, 'O sopro do vento', '', ARRAY['/covers/manga-kaze-p1.jpg','/covers/manga-kaze-p2.jpg','/covers/manga-kaze-p3.jpg','/covers/manga-kaze-p4.jpg'], true), ('kaze-no-kokoro', 2, 'A prova do dojo', E'O mestre Goro não falou uma palavra durante a primeira hora. Apenas empilhou dois bokken no centro do tatame e apontou para o chão.\n\n— Escolhe um e me devolve quando o vento parar — disse por fim.\n\nSano pegou o mais pesado. O vento, claro, não parou. Parou ele.', ARRAY[]::text[], false), ('kaze-no-kokoro', 3, 'A primeira lâmina', E'Na aldeia diziam que a lâmina de Sano nunca tocava carne por acaso. Ele preferia acreditar que era o vento que desviava.\n\nMas naquela noite, contra o bandido do portão leste, não houve vento — só o que ele treinou, o que ele perdeu e o que ele ainda não sabia nomear.', ARRAY[]::text[], false), ('ramen-da-meia-noite', 1, 'O cliente sem nome', '', ARRAY[]::text[], true), ('ramen-da-meia-noite', 2, 'Caldo de segunda-feira', '', ARRAY[]::text[], false), ('sigilo', 1, 'A testemunha', '', ARRAY[]::text[], true), ('sigilo', 2, 'Chuva ácida', '', ARRAY[]::text[], false), ('estrela-cadente', 1, 'O mesmo desejo', '', ARRAY[]::text[], true), ('estrela-cadente', 2, 'Pedaço de festival', '', ARRAY[]::text[], false)) AS e(slug, number, title, body, images, is_free) ON e.slug = c.slug WHERE NOT EXISTS (SELECT 1 FROM public.content_episodes ce WHERE ce.content_id = c.id AND ce.number = e.number);